assessmentFields.push(['Extended protocol context',[
 ['Respiratory rate (breaths/min)','Respiratory rate (breaths/min)','number',1,80],['SpO2 (%)','Oxygen saturation (%)','number',30,100],['Lactate (mmol/L)','Lactate (mmol/L)','number',0,40],['Central catheter present','Central catheter present','yesno'],['Prior MRSA','Prior MRSA colonisation / infection','yesno'],['Prior ESBL','Prior ESBL colonisation / infection','yesno'],['Prior CRE','Prior CRE colonisation / infection','yesno'],['Quinolone prophylaxis','Prior quinolone prophylaxis','yesno'],['Antifungal prophylaxis','Prior antifungal prophylaxis','select',['None','Azole','Other']],['Fever days on antibiotics','Persistent fever days on antibiotics','number',0,90],['Broad-spectrum antibiotic days','Days of broad-spectrum antibacterial therapy','number',0,90],['Oral tolerance','Can swallow and absorb oral treatment','yesno'],['Reliable follow-up','Reliable home support and follow-up','yesno'],['Already appropriate therapy on arrival','Already on appropriate therapy at arrival','yesno'],['Transferred after antibiotics','Transferred after antibiotics elsewhere','yesno'],['Comfort care only','Comfort-care / palliative-only plan','yesno']
]]);
TABS.push('Protocol review');navs.push('Scope & evidence');
const scopeCoverage=[
 ['FN definition & MASCC','Implemented, draft','FN criteria and calculated MASCC; unknowns shown; source validation still required.'],
 ['Six subtype workflow','Partial · review mapper','Candidate pathways and overlapping flags; no finalized automatic treatment branch.'],
 ['Ready-to-sign order sets','Not implemented','Care records/checklists are documentation, not executable order sets or signatures.'],
 ['Medication doses / renal adjustment','Not implemented','Demo regimen history only. Pharmacist-approved formulary, reaction and renal rules required.'],
 ['Diagnosis inputs','Expanded, partial','RR, SpO2, lactate, resistant-organism history, prophylaxis, fever duration, oral tolerance and follow-up now collectable. Chemotherapy date and detailed liver tests remain incomplete.'],
 ['First appropriate antibiotic within 60 min','Partial data; no KPI','Triage checklist and recorded actual administration exist for demo cases. Eligibility, exclusions, regimen appropriateness and complete timestamp linkage are not fully implemented.'],
 ['Secondary metrics','Not implemented as formal metrics','MASCC exists; order-set adoption, concordance and form-completion-time indicators are not yet calculated.'],
 ['Drive / Google Sheets knowledge connector','Architecture changed / absent','Current version uses bundled JSON and local browser data, not a live Drive database.'],
 ['Sources, versions and governance','Partial','References visible; no approved per-rule release, accountable sign-off or monitored review cycle yet.'],
 ['Audit, safety, usability','Prototype implemented / validation pending','Local event log, reflection, FMEA and usability design. No immutable audit or completed representative-user study.'],
 ['Alerts and escalation','Prototype; scope extension','Pull-based CDS remains available. Foreground alerts and simulated escalation are additions to the original non-interruptive brief; external delivery absent.'],
 ['Hospital integration / roles / sync','Not implemented','No live EHR/LIS, shared backend or authenticated clinical roles. FHIR mappings are proposed only.']
];
function draftPathways(p){const a=assess(p),matches=[],warnings=[];const num=k=>typeof p[k]==='number'?p[k]:null;const systolic=num('Systolic BP (mmHg)'),anc=num('ANC (×10⁹/L)'),lactate=num('Lactate (mmol/L)');if(systolic!==null&&systolic<90||p['New confusion / neuro change']==='Yes')matches.push({code:'FN-3',label:'Possible instability · urgent assessment',why:'Recorded hypotension or altered mentation; verify recency and current clinical state.'});if(lactate!==null&&lactate>=2)warnings.push('Lactate ≥2 requires contextual review; it does not establish septic shock by itself.');if(p['Catheter infection']==='Yes')matches.push({code:'FN-4',label:'Suspected catheter infection module',why:'Recorded catheter-infection feature; confirm source and paired culture plan.'});if(['Prior MRSA','Prior ESBL','Prior CRE'].some(k=>p[k]==='Yes'))matches.push({code:'FN-5',label:'Resistant-organism risk module',why:'Resistance history recorded. Distinguish organism and susceptibility; no universal carbapenem choice.'});if(num('Fever days on antibiotics')>=4&&num('Broad-spectrum antibiotic days')>=4&&p['Expected ANC <0.1 for ≥7 days']==='Yes')matches.push({code:'FN-6',label:'Persistent-fever specialist review',why:'Draft review trigger: persistent fever on antibacterials with anticipated prolonged profound neutropenia. No automatic antifungal order.'});if(a.risk==='High'||anc!==null&&anc<.1)matches.push({code:'FN-2',label:'High-risk pathway review',why:anc!==null&&anc<.1?'ANC <0.1 is a high-risk trigger in the supplied capstone. Workbook final-risk formula may differ.':a.flags.join('; ')||'MASCC below 21.'});if(a.risk==='Low'&&p['Reliable follow-up']==='Yes'&&p['Oral tolerance']==='Yes'&&p['Quinolone prophylaxis']==='No')matches.push({code:'FN-1',label:'Low-risk outpatient eligibility review',why:'Low-risk assessment plus oral tolerance, follow-up and no quinolone prophylaxis recorded; further clinical/logistical checks required.'});else if(a.risk==='Low')warnings.push('Low MASCC/workbook risk does not complete outpatient eligibility: document prophylaxis, oral tolerance and reliable follow-up.');if(!matches.length)warnings.push('No candidate subtype established from available data; complete assessment.');if(anc!==null&&anc<.1&&a.risk==='Low')warnings.push('Source conflict: workbook risk says Low but capstone ANC-only criterion flags high-risk review. Source governance must resolve this; original workbook classification was preserved.');warnings.push('Candidate modules can overlap. Primary-subtype precedence is not clinically approved; do not collapse them into a single treatment order.');const fn=fnEligibility(p);if(fn.status!=='Numeric criteria met'){warnings.push('FN criteria are not established; FN treatment modules are withheld. Current instability can still require urgent assessment.');return{matches:matches.filter(m=>m.code==='FN-3'),warnings,fn,risk:a.risk}}return{matches,warnings,fn,risk:a.risk}}
function protocolReviewView(){const p=selected,x=draftPathways(p);return `<section class="panel"><div class="sectiontitle"><div><h2>Protocol review · ${esc(patientName(p))}</h2><p>Explainable candidate mapping against the attached capstone text.</p></div><button class="btn" onclick="openAssessment(false)">Complete protocol inputs</button></div><div class="notice"><b>Draft mapping — not a treatment recommendation.</b> FN state: ${esc(x.fn.status)}. No automatic drug selection, dosing, order signing or transmission.</div>${x.matches.map(m=>`<div class="safetyissue"><span class="pill">${m.code} · candidate</span><h3>${m.label}</h3><p>${esc(m.why)}</p></div>`).join('')}${x.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<details><summary>Missing extended context</summary><p>${esc(assessmentFields.find(g=>g[0]==='Extended protocol context')[1].filter(f=>p[f[0]]===null||p[f[0]]===undefined||p[f[0]]==='').map(f=>f[1]).join('; ')||'Extended fields entered; clinician validation remains required.')}</p></details><button class="btn" onclick="go('Scope & evidence')">Sources & implementation gaps →</button></section>`}
function scopeEvidenceView(){return header('Scope & evidence','Verified implementation coverage — no percentage-complete claim.',`<button class="btn" onclick="download('fn-scope-coverage.json',{source:'User-attached Pasted markdown(1).md',coverage:scopeCoverage,approval:'Draft, not clinically approved'})">Export coverage</button>`)+`<div class="banner">The attached text is a project specification. It is not a complete clinical guideline, a validated medication database or evidence of approval.</div><section class="panel"><h2>Requirements coverage</h2><div class="scroll"><table><thead><tr><th>Requirement</th><th>Current state</th><th>Evidence / remaining work</th></tr></thead><tbody>${scopeCoverage.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><h2>Source register · review pending</h2><p><a href="https://www.idsociety.org/practice-guideline/neutropenic-patients-with-cancer/" target="_blank" rel="noopener">IDSA FN 2010</a> · <a href="https://www.idsociety.org/practice-guideline/fever-and-neutropenia-in-adults-with-cancer/" target="_blank" rel="noopener">ASCO/IDSA outpatient 2018</a> · supplied ESMO 2016 / AHS 2014 pathway · MASCC workbook and capstone text.</p><p>These are named historical source versions, not a verified latest-guideline set. NCCN is mentioned by the brief but its current complete text was not supplied or validated. Institution, clinical owner, formulary, antibiogram, approval date and next review remain unassigned.</p><h3>Required text corrections</h3><p>Separate clinical instability from a confirmed sepsis/shock diagnosis. Lactate alone must not label shock. Persistent-fever antifungal decisions depend on high-risk status, duration of antibacterial therapy and expected neutropenia, clinical stability, fungal investigations and prior prophylaxis.</p><p>Separate immediate IgE-type reactions from severe delayed reactions such as SJS/TEN; no blanket allergy alternative should be encoded from this draft. Do not prescribe a fixed carbapenem backbone for all unstable patients or all resistance histories. Reconcile chest-imaging and observation policies across source versions.</p><h3>Next implementation priorities</h3><p>1. Clinical source reconciliation and approved medication tables.<br>2. Versioned editable order-set drafts with appropriate missing-data blocks.<br>3. Fully specified primary/secondary metrics with missing-data and exclusion reporting.<br>4. Authenticated backend, shared audit and real integration validation.</p></section>`}
const detailBeforeScope=detail;detail=function(){let h=detailBeforeScope();if(selected&&patientTab==='Protocol review')h+=protocolReviewView();return h};
const renderBeforeScope=render;render=function(){renderBeforeScope();if(view==='Scope & evidence')$('#app').innerHTML=scopeEvidenceView()};
